import type { FreeCamera, SceneContext } from "@babylonjs/lite";
import { attachConfigurableFreeControl } from "@babylonjs/lite";

function withKeyboardVariants(...base: string[]): readonly string[] {
  const variants = new Set<string>();

  for (const key of base) {
    variants.add(key);
    variants.add(key.toLowerCase());
    variants.add(key.toUpperCase());
  }

  return Object.freeze(Array.from(variants));
}

export function attachFlyControls(
  camera: FreeCamera,
  canvas: HTMLCanvasElement,
  scene: SceneContext,
): () => void {
  const options = {
    // Space rises, PageDown sinks.
    // Shift is intentionally not in either vertical key array.
    upKeys: withKeyboardVariants(" ", "Space", "Spacebar"),
    downKeys: withKeyboardVariants("PageDown", "Page Down", "PgDn"),

    // Left/Right Shift only boosts movement speed.
    fastKeys: withKeyboardVariants("Shift", "ShiftLeft", "ShiftRight"),
    fastMultiplier: 3,
  };

  const dispose = attachConfigurableFreeControl(camera, canvas, scene, options);
  let cleaned = false;

  return () => {
    if (cleaned) return;
    cleaned = true;

    if (typeof dispose === "function") {
      dispose();
    }
  };
}
```

I added `src/fly-controls.ts` to attach the library’s configurable free-camera controls with Space/PageDown for vertical movement and Shift mapped only as a 3x speed key, returning a dispose wrapper that calls the library’s cleanup. I was unsure about the exact package export path for the control function and whether the key arrays are matched against `event.key`, `event.code`, or normalized lowercase strings, so I included common variants for both Shift left/right and Space/PageDown.
